/**
 * Runtime layer for the calculated-field DSL — coercion + node
 * construction.
 *
 * Every `calc.*` builder funnels its inputs through `coerce()`, which
 * normalizes one of {already-an-Expr, typed AppField, raw literal}
 * into an `Expr<T>`. The builder then composes the resulting
 * `toCalcString()` closures into a parent node. No mutable AST — each
 * node carries its own serializer closure built at construction time.
 *
 * Wire-format choices baked in here:
 *   - Field refs emit `"<uuid>"` when the field has a UUID id, and
 *     `"<name>"` otherwise. Both forms parse on the server. The UUID
 *     form is preferred because it's rename-safe; the name form is
 *     the fallback for placeholder-id fields being created in the
 *     same compose (the server resolves the name within the request).
 *   - String literals are single-quoted with `''` escapes per the
 *     ANTLR grammar.
 *   - Boolean literals are `TRUE()` / `FALSE()` (the parser accepts
 *     both these and the bare keywords; the function form is the
 *     canonical shape per the Java test).
 */
import type { AppField, FieldScope } from "../../../core/types/app.js";
import { type Ref } from "../../shared/ref.js";
import type { Expr, ExprCardinality, ExprContext, ExprLike, ExprType } from "./types.js";
/**
 * Build an `Expr<T>` node from its type brand and a serializer
 * closure. Internal — public builders compose this.
 */
export declare function makeExpr<T extends ExprType, Cardinality extends ExprCardinality = "single", Context extends ExprContext = "standalone">(type: T, serialize: () => string, metadata?: {
    readonly cardinality?: Cardinality;
    readonly context?: Context;
}): Expr<T, Cardinality, Context>;
/**
 * True if `value` is already an `Expr<T>` (built by a prior `calc.*`
 * call or a pulled-expression marker). Discriminator-checked.
 */
export declare function isExpr(value: unknown): value is Expr<ExprType, ExprCardinality, ExprContext>;
/** Aggregate runtime context metadata for a composed expression. */
export declare function expressionContext(expressions: readonly Expr<ExprType, ExprCardinality, ExprContext>[]): ExprContext;
/** Build a scalar parent node while preserving record-context metadata. */
export declare function makeComposedExpr<T extends ExprType>(type: T, expressions: readonly Expr<ExprType, ExprCardinality, ExprContext>[], serialize: () => string): Expr<T, "single", ExprContext>;
/**
 * Build a comparison node, tagged so {@link assertCalculatedFieldRoot} can
 * reject it at the root of a calculation. The grammar's root production is
 * "expression", which covers arithmetic, function calls, column refs and
 * literals but NOT comparisons — those are a separate "boolean expression"
 * production reachable only as a function argument.
 */
export declare function makeComparisonExpr(expressions: readonly Expr<ExprType, ExprCardinality, ExprContext>[], serialize: () => string): Expr<"bool", "single", ExprContext>;
/**
 * Throw when `expression` is a comparison standing alone as a whole
 * calculated field. `owner` names the field in the message so the author can
 * find it without reading the generated HCL.
 *
 * Scoped to calculated fields: the provider runs
 * `aspectFieldCalculationValidateV3` on every create and update there, so the
 * shape is a hard apply failure. Automation calculation tasks validate only on
 * read, where the provider degrades to a diagnostic.
 */
export declare function assertCalculatedFieldRoot(expression: Expr<ExprType, ExprCardinality, ExprContext>, owner?: string): void;
/**
 * Emit the wire form of a field reference. UUID ids emit as
 * `"<uuid>"`; placeholder ids fall back to `"<name>"`. The server
 * accepts both inside the same compose body.
 *
 * Field name quoting uses `""` escapes (ANSI SQL double-quote
 * doubling) per the ANTLR grammar's IDENTIFIER_QUOTED rule.
 */
export declare function emitFieldRef(field: AppField<FieldScope>): string;
type WorkflowRefRenderer = (value: Ref<unknown, string>) => string;
/** Install the automation calculation parameter collector for one render. */
export declare function withWorkflowRefRenderer<T>(renderer: WorkflowRefRenderer, render: () => T): T;
/**
 * Quote a TS string for the wire. Single-quoted with `''` escapes per
 * the ANTLR grammar's STRING_LITERAL rule.
 */
export declare function emitStringLiteral(value: string): string;
/**
 * Normalize an `ExprLike<T>` into an `Expr<T>`. The three branches:
 *
 *   1. Already an `Expr<T>` (or a pulled-expression marker) → return
 *      verbatim.
 *   2. An `AppField` handle → wrap as an `Expr<...>` whose
 *      `toCalcString()` emits the wire field reference.
 *   3. A raw TS literal (number / string / boolean) → wrap as a
 *      typed literal expression.
 *
 * The function's input type is `ExprLike<T>` so TypeScript already
 * narrowed which `T` is expected at the call site; the runtime
 * branches just route the value through the right factory. Coercion
 * doesn't validate that the value's actual type matches `T` — the
 * compile-time `ExprLike<T>` union prevents the mismatch from ever
 * reaching here.
 */
export declare function coerce<T extends ExprType>(value: ExprLike<T>): Expr<T>;
export {};
